class Solution {
public:
    vector<int> findAnagrams(string s, string p) {
        vector<int> result;
        int n = s.size(), m = p.size();
        if (m > n) return result;

        vector<int> pCount(26, 0), wCount(26, 0);
        for (char c : p) pCount[c - 'a']++;

        for (int i = 0; i < m; i++) wCount[s[i] - 'a']++;

        int matches = 0;
        for (int i = 0; i < 26; i++) {
            if (pCount[i] == wCount[i]) matches++;
        }

        if (matches == 26) result.push_back(0);

        for (int i = m; i < n; i++) {
            int add = s[i] - 'a';
            int rem = s[i - m] - 'a';

            wCount[rem]--;
            if (wCount[rem] == pCount[rem]) matches++;
            else if (wCount[rem] + 1 == pCount[rem]) matches--;

            wCount[add]++;
            if (wCount[add] == pCount[add]) matches++;
            else if (wCount[add] - 1 == pCount[add]) matches--;

            if (matches == 26) result.push_back(i - m + 1);
        }

        return result;
    }
};
